import{_ as a,o as e,c as i,a2 as o}from"./chunks/framework.BqDA2HS7.js";const _=JSON.parse('{"title":"Static · 静态","description":"","frontmatter":{},"headers":[],"relativePath":"strategies/static.md","filePath":"strategies/static.md"}'),r={name:"strategies/static.md"};function d(s,t,c,l,n,h){return e(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="static-·-静态" tabindex="-1">Static · 静态 <a class="header-anchor" href="#static-·-静态" aria-label="Permalink to &quot;Static · 静态&quot;">​</a></h1><p>Static 在新任务开始时选一个执行模型，工具续接沿用选择。它不调用 Task Judge 或审核器。</p><h2 id="当前设置的真实含义" tabindex="-1">当前设置的真实含义 <a class="header-anchor" href="#当前设置的真实含义" aria-label="Permalink to &quot;当前设置的真实含义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>当前实现</th></tr></thead><tbody><tr><td>Fixed</td><td>固定使用共用设置中的“高效执行模型”及其推理等级</td></tr><tr><td>Random</td><td>按高效／强执行两个角色的冻结权重，每任务随机选择一次</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">当前 Random 的范围</p><p>当前版本不是任意数量模型的独立 Static 池。Task／Composite 有多模型池，Static 随机仍是 两个角色的加权对照。这里如实记录实现边界，不把计划中的产品形式描述为已完成。</p></div><p>“固定高效角色”是程序默认值，不表示用户曾主动配置，也不表示 Router 已经判断这个 模型对任务最合适。你选择哪个模型承担该角色，Static 就使用哪个。</p><h2 id="哪些配置必要" tabindex="-1">哪些配置必要 <a class="header-anchor" href="#哪些配置必要" aria-label="Permalink to &quot;哪些配置必要&quot;">​</a></h2><p>Fixed 只需要高效执行角色、真实推理参数、价格、能力、数据域和预算。 不需要强执行、任务判别和 Advisor 审核角色。</p><p>Random 需要两个执行角色及权重。权重 <code>1:1</code> 表示同等抽样概率；<code>3:1</code> 表示 75% 与 25%。 随机种子便于复现对照，不是模型质量或费用参数。续接不会重新抽样。</p><h2 id="典型用途" tabindex="-1">典型用途 <a class="header-anchor" href="#典型用途" aria-label="Permalink to &quot;典型用途&quot;">​</a></h2><p>先验证真实模型和原生工具，再作为其他策略的固定基线。随机模式适合实验， 不能保证每次选择质量达标或更省钱。</p><h2 id="轨迹应该看到什么" tabindex="-1">轨迹应该看到什么 <a class="header-anchor" href="#轨迹应该看到什么" aria-label="Permalink to &quot;轨迹应该看到什么&quot;">​</a></h2><p>固定／随机理由、选中的真实模型与推理等级、调用用途、费用和耗时。 如果 Fixed 产生额外 Judge 调用，需核对是否实际选择了其他策略。</p>',13)])])}const m=a(r,[["render",d]]);export{_ as __pageData,m as default};
